void draw_background_tiles(void)
{
    int tile_x;
    int tile_y;
    unsigned char *tile_descriptor;
    tile_y = 16;
    while (tile_y < vga_state.screen_height) {
        tile_x = 0;
        while (tile_x < vga_state.screen_width) {
            tile_descriptor = tile_art_base + background_tile_offsets[2 * tileid];
            draw_bob_sprite_entry(tile_descriptor, tile_x, tile_y);
            tile_x += *(short *)(tile_descriptor + 2);
        }
        tile_y += *(short *)(tile_descriptor + 4);
    }
}

void get_sprite_bounds(int *bounds, unsigned char *frame_info)
{
    sprite_metadata = frame_info;
    read_sprite_frame_bounds();
    bounds[0] += x_delta;
    bounds[1] += y_offset;
    bounds[2] = bounds[0] + width - 2;
    bounds[3] = bounds[1] + height - 2;
}

void get_sprite_collision_bounds(int *bounds, unsigned char *frame_info)
{
    sprite_metadata = frame_info;
    read_sprite_frame_bounds();
    bounds[0] += x_delta + 3;
    bounds[1] += y_offset + 3;
    bounds[2] = bounds[0] - 3 + width - 5;
    bounds[3] = bounds[1] - 3 + height - 5;
}

void rkt_mv(void)
{
    if (scan_code_bitmap[1].bytes.hi & 0x20) {
        if (mouse_btn != mouse_btn_old) {
            if (mouse_btn == 1) {
                query_mouse_sensitivity();
                x_cursor_sensitivity -= 2;
                mouse_sensitivity_y_axis -= 2;
                restore_mouse_driver_sensitivity();
            } else if (mouse_btn == 2) {
                query_mouse_sensitivity();
                x_cursor_sensitivity += 2;
                mouse_sensitivity_y_axis += 2;
                restore_mouse_driver_sensitivity();
            }
        }
    }
}
